using CampusServicePortal.DTOs.Events;
using CampusServicePortal.Services.Interfaces;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
namespace CampusServicePortal.Controllers;
[Route("api/events")][ApiController][Authorize]
public class EventsController(IEventService service) : ControllerBase { [HttpGet] public async Task<IActionResult> GetAll([FromQuery] bool includeInactive=false)=>Ok(await service.GetEventsAsync(User.IsInRole("Admin")&&includeInactive)); [HttpPost,Authorize(Roles="Admin")] public async Task<IActionResult> Create(SaveEventDto dto){try{var r=await service.SaveEventAsync(null,dto);return CreatedAtAction(nameof(GetAll),r);}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}} [HttpPut("{id:int}"),Authorize(Roles="Admin")] public async Task<IActionResult> Update(int id,SaveEventDto dto){try{return Ok(await service.SaveEventAsync(id,dto));}catch(KeyNotFoundException e){return NotFound(new{message=e.Message});}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}} [HttpDelete("{id:int}"),Authorize(Roles="Admin")] public async Task<IActionResult> Delete(int id){try{await service.DeactivateEventAsync(id);return Ok(new{message="Event cancelled."});}catch(KeyNotFoundException e){return NotFound(new{message=e.Message});}} [HttpGet("{id:int}/seats")] public async Task<IActionResult> Seats(int id)=>Ok(await service.GetSeatsAsync(id)); [HttpPost("{id:int}/seats"),Authorize(Roles="Admin")] public async Task<IActionResult> AddSeat(int id,CreateEventSeatDto dto){try{return Ok(await service.AddSeatAsync(id,dto));}catch(KeyNotFoundException e){return NotFound(new{message=e.Message});}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}} [HttpDelete("{id:int}/seats/{seatId:int}"),Authorize(Roles="Admin")] public async Task<IActionResult> RemoveSeat(int id,int seatId){try{await service.RemoveSeatAsync(id,seatId);return Ok(new{message="Seat removed."});}catch(KeyNotFoundException e){return NotFound(new{message=e.Message});}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}} }
